const body = $json.body ?? {};
const jobId = typeof body.job_id === 'string' ? body.job_id.trim() : '';
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(jobId)) {
  throw new Error('job_id must be a UUID v4');
}
return [{json:{job_id:jobId}}];

if (!$json.id) throw new Error('queued job not found or already processed');
const duration = Number($json.target_duration_seconds);
const wordTarget = Math.max(20, Math.round(duration * 1.9));
const sceneCount = duration === 15 ? 3 : duration === 30 ? 5 : duration === 45 ? 7 : 9;
const languageNames = {en:'English',pl:'Polish',ru:'Russian',uk:'Ukrainian'};
const prompt = [
  'Create narration and a scene plan for a factual vertical short video.',
  'Return JSON only. No markdown fences and no commentary.',
  'Language: ' + languageNames[$json.language] + '.',
  'Topic: ' + $json.topic,
  'Target duration: ' + duration + ' seconds.',
  'Target narration length: about ' + wordTarget + ' words. Prefer slightly shorter rather than longer.',
  'Use exactly ' + sceneCount + ' scenes.',
  'The script must be natural spoken language, concise, factual, and complete.',
  'Each scene must contain narration plus a concrete visual_query suitable for Wikimedia Commons.',
  'visual_query must describe an ordinary directly relevant image, not a rare edge case. Avoid eclipse, sunset, sunrise, storm, night, infographic, logo, portrait, or map unless the topic specifically requires it.',
  'Do not invent citations, URLs, or facts.',
  'Return exactly this shape:',
  '{"script":"full narration","scenes":[{"narration":"...","visual_query":"...","visual_description":"..."}]}',
  'The full script must equal the scene narrations joined in order, with normal spaces.'
].join('\n');
return [{json:{...$json,word_target:wordTarget,scene_count:sceneCount,prompt}}];

const raw = $json?.candidates?.[0]?.content?.parts?.[0]?.text;
if (typeof raw !== 'string' || !raw.trim()) throw new Error('Gemini returned no text');
const cleaned = raw.trim().replace(/^\`\`\`(?:json)?\s*/i,'').replace(/\s*\`\`\`$/,'');
let doc;
try { doc = JSON.parse(cleaned); } catch { throw new Error('Gemini script response is not valid JSON'); }
if (!doc || typeof doc.script !== 'string' || !Array.isArray(doc.scenes)) throw new Error('invalid script document');
const job = $('Build Script Prompt').item.json;
if (doc.scenes.length !== job.scene_count) throw new Error('scene count mismatch');
for (const [i,scene] of doc.scenes.entries()) {
  if (!scene || typeof scene.narration !== 'string' || !scene.narration.trim()) throw new Error('scene '+(i+1)+' narration missing');
  if (typeof scene.visual_query !== 'string' || !scene.visual_query.trim()) throw new Error('scene '+(i+1)+' visual_query missing');
  if (typeof scene.visual_description !== 'string' || !scene.visual_description.trim()) throw new Error('scene '+(i+1)+' visual_description missing');
}
const joined = doc.scenes.map(s=>s.narration.trim()).join(' ').replace(/\s+/g,' ').trim();
const script = doc.script.replace(/\s+/g,' ').trim();
if (script !== joined) doc.script = joined;
const words = doc.script.split(/\s+/).filter(Boolean).length;
if (words > Math.ceil(job.word_target * 1.25)) throw new Error('script exceeds maximum word budget');
return [{json:{
  job_id:job.id,
  script_text:doc.script,
  script_json:doc,
  word_count:words,
  target_duration_seconds:job.target_duration_seconds,
  language:job.language
}}];

const audio = $json?.steps?.flatMap(s=>Array.isArray(s.content)?s.content:[]).find(x=>x?.type==='audio');
if (!audio || typeof audio.data !== 'string' || !audio.data) throw new Error('Gemini TTS returned no audio');
const reserved = $('Reserve Single TTS').item.json;
const sampleRate = Number(audio.sample_rate);
const channels = Number(audio.channels);
if (!Number.isInteger(sampleRate) || sampleRate <= 0) throw new Error('invalid sample rate');
if (!Number.isInteger(channels) || channels <= 0) throw new Error('invalid channels');
const path = '/data/' + reserved.job_id + '-voice.pcm';
return [{
  json:{
    job_id:reserved.job_id,
    audio_path:path,
    audio_sample_rate:sampleRate,
    audio_channels:channels,
    audio_mime_type:String(audio.mime_type || 'audio/l16')
  },
  binary:{
    data:{
      data:audio.data,
      mimeType:'application/octet-stream',
      fileName:reserved.job_id+'-voice.pcm'
    }
  }
}];
